use super::*;
use chrono::{Datelike, Timelike};

const MANAGED_SCHEDULE_EXPORT_HEADER: &str =
    "# Generated by Zelyra setup. Re-run `zelyra setup --schema` to refresh.";

const SCHEDULE_SERVE_STATE_FILE: &str = "serve.json";
const SCHEDULE_PROBE_PATH: &str = zelyra_web::SCHEDULE_PROBE_PATH;
const SCHEDULER_MAX_CONCURRENT_JOBS: usize = 4;

/// Start the in-process scheduler. The caller must only invoke this from the
/// installed, active project service; the worker rechecks project source at
/// every minute boundary so removed or invalid declarations never run stale.
pub(super) fn start_resident_scheduler(
    entry_path: PathBuf,
    program: &zelyra_ast::Program,
) -> Result<std::thread::JoinHandle<()>, String> {
    validate_schedule_timezones(program)?;
    let entry_path = entry_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve scheduler entry: {error}"))?;
    let entry = entry_path.to_string_lossy().into_owned();
    let running = Arc::new(Mutex::new(std::collections::HashSet::<String>::new()));
    std::thread::Builder::new()
        .name("zelyra-scheduler".into())
        .spawn(move || {
            let mut source_invalid = false;
            loop {
                sleep_until_next_minute();
                let now = chrono::Utc::now();
                let due = match due_schedule_handlers_from_source(&entry, now) {
                    Ok(due) => {
                        if source_invalid {
                            eprintln!("zelyra scheduler: project checks passed again; schedule monitoring resumed");
                            source_invalid = false;
                        }
                        due
                    }
                    Err(error) => {
                        if !source_invalid {
                            eprintln!("zelyra scheduler: {error}; declared jobs are paused until the source is valid");
                            source_invalid = true;
                        }
                        continue;
                    }
                };
                for (schedule_name, handler) in due {
                    let admitted = running
                        .lock()
                        .is_ok_and(|mut active| claim_scheduler_job(&mut active, &schedule_name));
                    if !admitted {
                        eprintln!("zelyra scheduler: skipped `{schedule_name}` because the worker limit is reached or it is already running");
                        continue;
                    }
                    let entry = entry.clone();
                    let active = Arc::clone(&running);
                    let worker_name = schedule_name.clone();
                    let spawn_result = std::thread::Builder::new()
                        .name(format!("zelyra-job-{worker_name}"))
                        .spawn(move || {
                            eprintln!("zelyra scheduler: starting `{worker_name}` ({handler})");
                            let result = env::current_exe()
                                .map_err(|error| error.to_string())
                                .and_then(|executable| {
                                    Command::new(executable)
                                        .args(["run", &entry, "--entry", &handler])
                                        .status()
                                        .map_err(|error| error.to_string())
                                });
                            match result {
                                Ok(status) if status.success() => {
                                    eprintln!("zelyra scheduler: `{worker_name}` completed successfully");
                                }
                                Ok(status) => {
                                    eprintln!("zelyra scheduler: `{worker_name}` failed with {status}");
                                }
                                Err(error) => {
                                    eprintln!("zelyra scheduler: `{worker_name}` could not start: {error}");
                                }
                            }
                            if let Ok(mut active) = active.lock() {
                                active.remove(&worker_name);
                            }
                        });
                    if let Err(error) = spawn_result {
                        if let Ok(mut active) = running.lock() {
                            active.remove(&schedule_name);
                        }
                        eprintln!("zelyra scheduler: could not start worker `{schedule_name}`: {error}");
                    }
                }
            }
        })
        .map_err(|error| format!("cannot start the in-process scheduler: {error}"))
}

fn validate_schedule_timezones(program: &zelyra_ast::Program) -> Result<(), String> {
    for schedule in &program.schedules {
        parse_schedule_timezone(schedule)?;
    }
    Ok(())
}

fn claim_scheduler_job(
    active: &mut std::collections::HashSet<String>,
    schedule_name: &str,
) -> bool {
    if active.len() >= SCHEDULER_MAX_CONCURRENT_JOBS || active.contains(schedule_name) {
        return false;
    }
    active.insert(schedule_name.to_owned())
}

fn parse_schedule_timezone(schedule: &zelyra_ast::ScheduleDef) -> Result<chrono_tz::Tz, String> {
    let name = schedule.timezone.as_deref().unwrap_or("UTC");
    name.parse::<chrono_tz::Tz>().map_err(|_| {
        format!(
            "schedule `{}` uses unknown IANA timezone `{name}`",
            schedule.name
        )
    })
}

fn due_schedule_handlers(
    program: &zelyra_ast::Program,
    now_utc: chrono::DateTime<chrono::Utc>,
) -> Result<Vec<(String, String)>, String> {
    let mut due = Vec::new();
    for schedule in &program.schedules {
        let timezone = parse_schedule_timezone(schedule)?;
        let local = now_utc.with_timezone(&timezone);
        if !cron_matches_local_minute(&schedule.cron, &local)? {
            continue;
        }
        let command = program
            .commands
            .iter()
            .find(|command| command.name == schedule.command)
            .ok_or_else(|| format!("schedule `{}` references an unknown command", schedule.name))?;
        due.push((schedule.name.clone(), command.handler.clone()));
    }
    Ok(due)
}

fn due_schedule_handlers_from_source(
    entry: &str,
    now_utc: chrono::DateTime<chrono::Utc>,
) -> Result<Vec<(String, String)>, String> {
    let program = validate(entry).map_err(|()| "project compiler checks failed".to_owned())?;
    due_schedule_handlers(&program, now_utc)
}

fn cron_matches_local_minute(
    expression: &str,
    local: &chrono::DateTime<chrono_tz::Tz>,
) -> Result<bool, String> {
    let fields = expression.split_ascii_whitespace().collect::<Vec<_>>();
    if fields.len() != 5 {
        return Err("cron expression must contain five fields".into());
    }
    let minute = cron_field_matches(fields[0], 0, 59, local.minute())?;
    let hour = cron_field_matches(fields[1], 0, 23, local.hour())?;
    let month_day = cron_field_matches(fields[2], 1, 31, local.day())?;
    let month = cron_field_matches(fields[3], 1, 12, local.month())?;
    let weekday_value = local.weekday().num_days_from_sunday();
    let weekday = cron_field_matches(fields[4], 0, 7, weekday_value)?
        || (weekday_value == 0 && cron_field_matches(fields[4], 0, 7, 7)?);
    // Match the conventional cron rule: when both day-of-month and
    // day-of-week are restricted, either one may select the day.
    let day = if fields[2] == "*" {
        weekday
    } else if fields[4] == "*" {
        month_day
    } else {
        month_day || weekday
    };
    Ok(minute && hour && month && day)
}

fn cron_field_matches(field: &str, minimum: u32, maximum: u32, value: u32) -> Result<bool, String> {
    for item in field.split(',') {
        let (base, step) = match item.split_once('/') {
            Some((base, step)) => {
                let step = step
                    .parse::<u32>()
                    .ok()
                    .filter(|step| *step > 0)
                    .ok_or_else(|| format!("invalid cron step in `{item}`"))?;
                (base, step)
            }
            None => (item, 1),
        };
        let (start, end) = if base == "*" {
            (minimum, maximum)
        } else if let Some((start, end)) = base.split_once('-') {
            let start = start
                .parse::<u32>()
                .map_err(|_| format!("invalid cron range in `{item}`"))?;
            let end = end
                .parse::<u32>()
                .map_err(|_| format!("invalid cron range in `{item}`"))?;
            (start, end)
        } else {
            let start = base
                .parse::<u32>()
                .map_err(|_| format!("invalid cron value in `{item}`"))?;
            (start, if item.contains('/') { maximum } else { start })
        };
        if start < minimum || end > maximum || start > end {
            return Err(format!(
                "cron value `{item}` is outside {minimum}..={maximum}"
            ));
        }
        let normalized = if maximum == 7 && value == 0 { 0 } else { value };
        if normalized >= start && normalized <= end && (normalized - start) % step == 0 {
            return Ok(true);
        }
    }
    Ok(false)
}

fn sleep_until_next_minute() {
    let now = chrono::Utc::now();
    let seconds = 60_u64.saturating_sub(u64::from(now.second()));
    let remaining = std::time::Duration::from_secs(seconds).saturating_sub(
        std::time::Duration::from_nanos(u64::from(now.timestamp_subsec_nanos())),
    );
    std::thread::sleep(remaining);
}

struct ScheduleServeState {
    endpoint: String,
    token: String,
}

pub(super) struct ScheduleServeStateGuard {
    path: PathBuf,
    token: String,
}

impl Drop for ScheduleServeStateGuard {
    fn drop(&mut self) {
        let Ok(contents) = std::fs::read(&self.path) else {
            return;
        };
        let Ok(state) = serde_json::from_slice::<serde_json::Value>(&contents) else {
            return;
        };
        if state.get("token").and_then(serde_json::Value::as_str) == Some(&self.token) {
            let _ = std::fs::remove_file(&self.path);
        }
    }
}

pub(super) fn task_command(mut args: impl Iterator<Item = String>) -> ExitCode {
    let Some(action) = args.next() else {
        task_usage();
        return ExitCode::from(2);
    };
    match action.as_str() {
        "list" => {
            let Some(path) = args.next() else {
                task_usage();
                return ExitCode::from(2);
            };
            let json = match args.next().as_deref() {
                None => false,
                Some("--json") => true,
                _ => {
                    task_usage();
                    return ExitCode::from(2);
                }
            };
            if args.next().is_some() {
                task_usage();
                return ExitCode::from(2);
            }
            let Ok(program) = validate(&path) else {
                return ExitCode::from(1);
            };
            if json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&json!({
                        "schema_version": 1,
                        "commands": program.commands.iter().map(|command| {
                            let function = program.functions.iter().find(|function| function.name == command.handler);
                            json!({
                                "name": command.name,
                                "handler": command.handler,
                                "description": command.description,
                                "source_line": command.span.line,
                                "parameters": function.map(|function| function.params.iter().map(|parameter| json!({"name": parameter.name, "type": parameter.ty.to_string()})).collect::<Vec<_>>()).unwrap_or_default(),
                            })
                        }).collect::<Vec<_>>(),
                    }))
                    .expect("task inventory JSON is serializable")
                );
            } else if program.commands.is_empty() {
                println!("No commands declared in {path}");
            } else {
                for command in &program.commands {
                    let function = program
                        .functions
                        .iter()
                        .find(|function| function.name == command.handler);
                    let parameters = function
                        .map(|function| {
                            function
                                .params
                                .iter()
                                .map(|parameter| format!("{}: {}", parameter.name, parameter.ty))
                                .collect::<Vec<_>>()
                                .join(", ")
                        })
                        .unwrap_or_default();
                    println!("{}({}) -> {}", command.name, parameters, command.handler);
                    if let Some(description) = &command.description {
                        println!("  {description}");
                    }
                }
            }
            ExitCode::SUCCESS
        }
        "run" => {
            let Some(path) = args.next() else {
                task_usage();
                return ExitCode::from(2);
            };
            let Some(name) = args.next() else {
                task_usage();
                return ExitCode::from(2);
            };
            let mut entry_args = None;
            let mut max_steps = None;
            while let Some(argument) = args.next() {
                match argument.as_str() {
                    "--args" if entry_args.is_none() => match args.next() {
                        Some(value) => entry_args = Some(value),
                        None => {
                            task_usage();
                            return ExitCode::from(2);
                        }
                    },
                    "--max-steps" if max_steps.is_none() => match args.next() {
                        Some(value) => max_steps = Some(value),
                        None => {
                            task_usage();
                            return ExitCode::from(2);
                        }
                    },
                    _ => {
                        task_usage();
                        return ExitCode::from(2);
                    }
                }
            }
            let Ok(program) = validate(&path) else {
                return ExitCode::from(1);
            };
            let Some(command) = program.commands.iter().find(|command| command.name == name) else {
                eprintln!("error[E-TASK-002]: command `{name}` was not declared in `{path}`");
                return ExitCode::from(2);
            };
            let mut process = match env::current_exe() {
                Ok(executable) => Command::new(executable),
                Err(error) => {
                    eprintln!("error[E-TASK-003]: cannot locate Zelyra executable: {error}");
                    return ExitCode::from(1);
                }
            };
            process.args(["run", &path, "--entry", &command.handler]);
            if let Some(entry_args) = entry_args {
                process.args(["--entry-args", &entry_args]);
            }
            if let Some(max_steps) = max_steps {
                process.args(["--max-steps", &max_steps]);
            }
            match process.status() {
                Ok(status) if status.success() => ExitCode::SUCCESS,
                Ok(status) => ExitCode::from(
                    status
                        .code()
                        .and_then(|code| u8::try_from(code).ok())
                        .unwrap_or(1),
                ),
                Err(error) => {
                    eprintln!("error[E-TASK-003]: could not start command `{name}`: {error}");
                    ExitCode::from(1)
                }
            }
        }
        _ => {
            task_usage();
            ExitCode::from(2)
        }
    }
}

pub(super) fn schedule_command(mut args: impl Iterator<Item = String>) -> ExitCode {
    let Some(action) = args.next() else {
        schedule_usage();
        return ExitCode::from(2);
    };
    let Some(path) = args.next() else {
        schedule_usage();
        return ExitCode::from(2);
    };
    match action.as_str() {
        "trigger" => {
            let Some(flag) = args.next() else {
                schedule_usage();
                return ExitCode::from(2);
            };
            let Some(name) = args.next() else {
                schedule_usage();
                return ExitCode::from(2);
            };
            if flag != "--name" || name.is_empty() || args.next().is_some() {
                schedule_usage();
                return ExitCode::from(2);
            }
            trigger_schedule(&path, &name)
        }
        "list" => {
            let json = match args.next().as_deref() {
                None => false,
                Some("--json") => true,
                _ => {
                    schedule_usage();
                    return ExitCode::from(2);
                }
            };
            if args.next().is_some() {
                schedule_usage();
                return ExitCode::from(2);
            }
            let Ok(program) = validate(&path) else {
                return ExitCode::from(1);
            };
            if json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&json!({
                        "schema_version": 1,
                        "schedules": program.schedules.iter().map(|schedule| json!({
                            "name": schedule.name,
                            "command": schedule.command,
                            "cron": schedule.cron,
                            "timezone": schedule.timezone,
                            "source_line": schedule.span.line,
                        })).collect::<Vec<_>>(),
                    }))
                    .expect("schedule inventory JSON is serializable")
                );
            } else if program.schedules.is_empty() {
                println!("No schedules declared in {path}");
            } else {
                for schedule in &program.schedules {
                    println!(
                        "{}: {}  {}",
                        schedule.name,
                        schedule.cron,
                        schedule.timezone.as_deref().unwrap_or("UTC (default)")
                    );
                }
            }
            ExitCode::SUCCESS
        }
        "export" => {
            let mut format_seen = false;
            let mut output = None;
            while let Some(argument) = args.next() {
                match argument.as_str() {
                    "--format" if !format_seen => match args.next() {
                        Some(value) if value == "cron" => format_seen = true,
                        _ => {
                            schedule_usage();
                            return ExitCode::from(2);
                        }
                    },
                    "--output" if output.is_none() => match args.next() {
                        Some(value) if !value.is_empty() => output = Some(value),
                        _ => {
                            schedule_usage();
                            return ExitCode::from(2);
                        }
                    },
                    _ => {
                        schedule_usage();
                        return ExitCode::from(2);
                    }
                }
            }
            let Ok(program) = validate(&path) else {
                return ExitCode::from(1);
            };
            let cron = match render_schedule_export(&path, &program) {
                Ok(cron) => cron,
                Err(error) => {
                    eprintln!("error[E-TASK-003]: {error}");
                    return ExitCode::from(1);
                }
            };
            eprintln!("This is a legacy external cron preview. Do not install it alongside the integrated Zelyra service. Zelyra did not install or enable a scheduler.");
            if let Some(output) = output {
                let project_root = match std::path::Path::new(&path).canonicalize().map(|entry| {
                    entry
                        .parent()
                        .unwrap_or(std::path::Path::new("."))
                        .to_path_buf()
                }) {
                    Ok(root) => root,
                    Err(error) => {
                        eprintln!("error[E-TASK-003]: cannot resolve project root: {error}");
                        return ExitCode::from(1);
                    }
                };
                match write_schedule_export(&project_root, &output, cron.as_bytes()) {
                    Ok(path) => eprintln!("Cron preview written to {}; review the legacy/external-only warning above before use.", path.display()),
                    Err(message) => {
                        eprintln!("error[E-TASK-004]: {message}");
                        return ExitCode::from(1);
                    }
                }
            } else {
                print!("{cron}");
            }
            ExitCode::SUCCESS
        }
        _ => {
            schedule_usage();
            ExitCode::from(2)
        }
    }
}

fn trigger_schedule(path: &str, name: &str) -> ExitCode {
    let Ok(program) = validate(path) else {
        return ExitCode::from(1);
    };
    let Some(schedule) = program
        .schedules
        .iter()
        .find(|schedule| schedule.name == name)
    else {
        eprintln!("error[E-TASK-002]: schedule `{name}` was not declared in `{path}`");
        return ExitCode::from(2);
    };
    let Some(_command) = program
        .commands
        .iter()
        .find(|command| command.name == schedule.command)
    else {
        eprintln!("error[E-TASK-002]: schedule `{name}` has no checked command");
        return ExitCode::from(1);
    };
    let project_root = match std::path::Path::new(path)
        .canonicalize()
        .ok()
        .and_then(|entry| entry.parent().map(std::path::Path::to_path_buf))
    {
        Some(root) => root,
        None => {
            eprintln!("error[E-TASK-003]: cannot resolve project root for `{path}`");
            return ExitCode::from(1);
        }
    };
    if !super::service_cli::current_project_service_is_active(&project_root) {
        eprintln!(
            "schedule `{name}` skipped: this project's Zelyra service is not installed and active"
        );
        return ExitCode::SUCCESS;
    }
    let state_path = project_root.join(".zelyra").join(SCHEDULE_SERVE_STATE_FILE);
    let state = match read_schedule_serve_state(&state_path) {
        Ok(Some(state)) => state,
        Ok(None) => {
            eprintln!("schedule `{name}` skipped: this project's `serve` is not running");
            return ExitCode::SUCCESS;
        }
        Err(error) => {
            eprintln!("error[E-TASK-004]: {error}");
            return ExitCode::from(1);
        }
    };
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(std::time::Duration::from_secs(2)))
        .proxy(None)
        .build()
        .into();
    let response = agent
        .post(&state.endpoint)
        .header("x-zelyra-schedule-token", &state.token)
        .send_empty();
    match response {
        Ok(response) if response.status() == 204 => {}
        Ok(response) => {
            eprintln!(
                "schedule `{name}` skipped: serve rejected the private probe (HTTP {})",
                response.status()
            );
            return ExitCode::SUCCESS;
        }
        Err(error) => {
            eprintln!("schedule `{name}` skipped: this project's `serve` is not running ({error})");
            return ExitCode::SUCCESS;
        }
    }
    eprintln!("schedule `{name}` skipped: the active project service runs declared schedules in-process; do not install this legacy cron trigger");
    ExitCode::SUCCESS
}

fn read_schedule_serve_state(path: &std::path::Path) -> Result<Option<ScheduleServeState>, String> {
    let state_directory = path
        .parent()
        .ok_or_else(|| "schedule server state has no parent directory".to_owned())?;
    let directory_metadata = match std::fs::symlink_metadata(state_directory) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(format!("cannot inspect scheduler state directory: {error}")),
    };
    if directory_metadata.file_type().is_symlink() || !directory_metadata.is_dir() {
        return Err("schedule server state directory is not a safe directory".into());
    }
    let metadata = match std::fs::symlink_metadata(path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(format!("cannot inspect schedule server state: {error}")),
    };
    if metadata.file_type().is_symlink() || !metadata.is_file() || metadata.len() > 4096 {
        return Err("schedule server state is not a safe, bounded regular file".into());
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        if metadata.permissions().mode() & 0o077 != 0
            || directory_metadata.permissions().mode() & 0o077 != 0
        {
            return Err("schedule server state permissions are too broad".into());
        }
    }
    let bytes = std::fs::read(path)
        .map_err(|error| format!("cannot read schedule server state: {error}"))?;
    let value: serde_json::Value = serde_json::from_slice(&bytes)
        .map_err(|_| "schedule server state is invalid".to_owned())?;
    if value.get("version").and_then(serde_json::Value::as_u64) != Some(1) {
        return Err("schedule server state has an unsupported version".into());
    }
    let endpoint = value
        .get("endpoint")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| "schedule server state has no endpoint".to_owned())?;
    let token = value
        .get("token")
        .and_then(serde_json::Value::as_str)
        .filter(|token| token.len() == 64 && token.bytes().all(|byte| byte.is_ascii_hexdigit()))
        .ok_or_else(|| "schedule server state has no valid token".to_owned())?;
    let url = url::Url::parse(endpoint)
        .map_err(|_| "schedule server state endpoint is invalid".to_owned())?;
    let loopback = url.host().is_some_and(|host| {
        matches!(host, url::Host::Ipv4(ip) if ip.is_loopback())
            || matches!(host, url::Host::Ipv6(ip) if ip.is_loopback())
    });
    if url.scheme() != "http"
        || !loopback
        || url.path() != SCHEDULE_PROBE_PATH
        || url.port().is_none()
        || url.username() != ""
        || url.password().is_some()
        || url.query().is_some()
        || url.fragment().is_some()
    {
        return Err("schedule server state endpoint is not a loopback HTTP URL".into());
    }
    Ok(Some(ScheduleServeState {
        endpoint: endpoint.to_owned(),
        token: token.to_owned(),
    }))
}

/// Prepare schedules after an explicit project database/schema setup. Mail
/// schedules need the outbox table; cron export is a project-owned artifact
/// and is refreshed only when Zelyra owns the previous generated file.
pub(super) fn setup_declared_schedules(
    entry_path: &std::path::Path,
) -> Result<Vec<String>, String> {
    if !entry_path.is_file() {
        return Ok(Vec::new());
    }
    let entry_metadata = std::fs::symlink_metadata(entry_path).map_err(|error| {
        format!(
            "cannot inspect project entry `{}`: {error}",
            entry_path.display()
        )
    })?;
    if entry_metadata.file_type().is_symlink() {
        return Err(format!(
            "refusing to prepare schedules from symlinked entry `{}`",
            entry_path.display()
        ));
    }
    let canonical_entry = entry_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve project entry: {error}"))?;
    let project_root = canonical_entry
        .parent()
        .ok_or_else(|| "project entry has no parent directory".to_owned())?
        .to_path_buf();
    if canonical_entry.parent() != Some(project_root.as_path()) {
        return Err("project entry resolves outside the configured project root".into());
    }
    let entry = entry_path.to_string_lossy().into_owned();
    let loaded = load_project(&entry).map_err(|_| {
        "cannot prepare schedules because the project did not pass compiler validation".to_owned()
    })?;
    let program = loaded.program;
    if program.schedules.is_empty() {
        return remove_managed_schedule_export(&project_root, "no schedules are declared");
    }

    let mut messages = Vec::new();
    let has_mail_schedule = program.schedules.iter().any(|schedule| {
        let Some(command) = program
            .commands
            .iter()
            .find(|command| command.name == schedule.command)
        else {
            return false;
        };
        program
            .functions
            .iter()
            .find(|function| function.name == command.handler)
            .is_some_and(|function| {
                function
                    .capabilities
                    .iter()
                    .any(|capability| capability == "Email")
            })
    });
    if has_mail_schedule {
        let schema = build_schema(&program).map_err(|errors| {
            format!(
                "cannot prepare the outbox because the project schema is invalid: {}",
                errors
                    .iter()
                    .map(|error| error.message.as_str())
                    .collect::<Vec<_>>()
                    .join("; ")
            )
        })?;
        if schema.backend() != Backend::MariaDb {
            return Err(
                "scheduled email currently requires a MariaDB project because the outbox backend is MariaDB".into(),
            );
        }
        let database_url =
            outbox_cli::project_outbox_database_url(&entry, &schema)?.ok_or_else(|| {
                "scheduled email requires a configured project database URL".to_owned()
            })?;
        zelyra_database::outbox::ensure_mariadb_outbox(&database_url)
            .map_err(|error| format!("could not initialize the scheduled-email outbox: {error}"))?;
        messages.push("scheduled-email outbox is ready (repeat-safe setup)".into());
    }

    messages.extend(remove_managed_schedule_export(
        &project_root,
        "resident scheduling no longer uses project cron exports",
    )?);
    messages.push(
        "declared schedules are configured for execution by this project's active Zelyra service"
            .into(),
    );
    Ok(messages)
}

fn remove_managed_schedule_export(
    project_root: &std::path::Path,
    reason: &str,
) -> Result<Vec<String>, String> {
    let state_directory = project_root.join(".zelyra");
    let state_metadata = match std::fs::symlink_metadata(&state_directory) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
            return Err(format!(
                "refusing to inspect schedules in unsafe state directory `{}`",
                state_directory.display()
            ));
        }
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => {
            return Err(format!(
                "cannot inspect scheduler state `{}`: {error}",
                state_directory.display()
            ));
        }
    };
    let _ = state_metadata;
    let export_path = state_directory.join("schedules.cron");
    let metadata = match std::fs::symlink_metadata(&export_path) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
            return Err(format!(
                "refusing to remove non-file or symlinked schedule export `{}`",
                export_path.display()
            ));
        }
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => {
            return Err(format!(
                "cannot inspect schedule export `{}`: {error}",
                export_path.display()
            ));
        }
    };
    let _ = metadata;
    let existing = std::fs::read(&export_path).map_err(|error| {
        format!(
            "cannot read schedule export `{}`: {error}",
            export_path.display()
        )
    })?;
    if !existing.starts_with(MANAGED_SCHEDULE_EXPORT_HEADER.as_bytes()) {
        return Err(format!(
            "schedule export `{}` exists but is not managed by Zelyra; it was left unchanged",
            export_path.display()
        ));
    }
    std::fs::remove_file(&export_path).map_err(|error| {
        format!(
            "cannot remove obsolete Zelyra schedule export `{}`: {error}",
            export_path.display()
        )
    })?;
    Ok(vec![format!(
        "removed obsolete Zelyra schedule export at {}: {reason}",
        export_path.display(),
    )])
}

fn render_schedule_export(path: &str, program: &zelyra_ast::Program) -> Result<String, String> {
    let absolute_entry = std::path::Path::new(path)
        .canonicalize()
        .map_err(|error| format!("cannot resolve `{path}`: {error}"))?;
    let project_root = absolute_entry.parent().unwrap_or(std::path::Path::new("."));
    let executable =
        env::current_exe().map_err(|error| format!("cannot locate Zelyra executable: {error}"))?;
    if absolute_entry
        .as_os_str()
        .to_string_lossy()
        .chars()
        .any(char::is_control)
        || executable
            .as_os_str()
            .to_string_lossy()
            .chars()
            .any(char::is_control)
    {
        return Err("cron export cannot safely represent control characters in the project or executable path".into());
    }
    let mut cron = String::new();
    for schedule in &program.schedules {
        let timezone = schedule.timezone.as_deref().unwrap_or("UTC");
        writeln!(cron, "# Zelyra schedule: {}", schedule.name)
            .expect("writing to a String cannot fail");
        writeln!(cron, "CRON_TZ={timezone}").expect("writing to a String cannot fail");
        writeln!(
            cron,
            "{} cd {} && {} schedule trigger {} --name {}",
            schedule.cron,
            shell_quote(&project_root.to_string_lossy()),
            shell_quote(&executable.to_string_lossy()),
            shell_quote(&absolute_entry.to_string_lossy()),
            shell_quote(&schedule.name)
        )
        .expect("writing to a String cannot fail");
        cron.push('\n');
    }
    Ok(cron)
}

pub(super) fn activate_schedule_probe(
    entry_path: &std::path::Path,
    address: std::net::SocketAddr,
) -> Result<(String, ScheduleServeStateGuard), String> {
    let project_root = entry_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve schedule project entry: {error}"))?
        .parent()
        .ok_or_else(|| "schedule project entry has no parent directory".to_owned())?
        .to_path_buf();
    let state_directory = project_root.join(".zelyra");
    match std::fs::symlink_metadata(&state_directory) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
            return Err("refusing to use unsafe scheduler state directory".into());
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            std::fs::create_dir(&state_directory)
                .map_err(|error| format!("cannot create scheduler state directory: {error}"))?;
        }
        Err(error) => {
            return Err(format!("cannot inspect scheduler state directory: {error}"));
        }
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&state_directory, std::fs::Permissions::from_mode(0o700))
            .map_err(|error| format!("cannot protect scheduler state directory: {error}"))?;
    }

    let state_path = state_directory.join(SCHEDULE_SERVE_STATE_FILE);
    if let Ok(metadata) = std::fs::symlink_metadata(&state_path) {
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err("refusing to replace unsafe schedule server state".into());
        }
    }
    let token = CsrfProtection::generate()
        .map_err(|_| "cannot generate a secure scheduler token".to_owned())?
        .token()
        .to_owned();
    let loopback = match address.ip() {
        std::net::IpAddr::V4(_) => format!("127.0.0.1:{}", address.port()),
        std::net::IpAddr::V6(_) => format!("[::1]:{}", address.port()),
    };
    let endpoint = format!("http://{loopback}{SCHEDULE_PROBE_PATH}");
    let contents = serde_json::to_vec(&json!({
        "version": 1,
        "endpoint": endpoint,
        "token": token,
    }))
    .map_err(|_| "cannot encode schedule server state".to_owned())?;
    let temporary = state_directory.join(format!(".serve-{}.tmp", std::process::id()));
    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let mut file = options
        .open(&temporary)
        .map_err(|error| format!("cannot create schedule server state: {error}"))?;
    if let Err(error) = file.write_all(&contents).and_then(|()| file.sync_all()) {
        drop(file);
        let _ = std::fs::remove_file(&temporary);
        return Err(format!("cannot write schedule server state: {error}"));
    }
    drop(file);
    #[cfg(windows)]
    if state_path.exists() {
        let backup = state_directory.join(format!(".serve-{}.bak", std::process::id()));
        if backup.exists() {
            let _ = std::fs::remove_file(&temporary);
            return Err("a previous schedule server state backup needs recovery".into());
        }
        if let Err(error) = std::fs::rename(&state_path, &backup) {
            let _ = std::fs::remove_file(&temporary);
            return Err(format!(
                "cannot preserve previous schedule server state: {error}"
            ));
        }
        if let Err(error) = std::fs::rename(&temporary, &state_path) {
            let _ = std::fs::rename(&backup, &state_path);
            let _ = std::fs::remove_file(&temporary);
            return Err(format!("cannot replace schedule server state: {error}"));
        }
        std::fs::remove_file(backup)
            .map_err(|error| format!("cannot remove schedule state backup: {error}"))?;
    } else {
        std::fs::rename(&temporary, &state_path)
            .map_err(|error| format!("cannot publish schedule server state: {error}"))?;
    }
    #[cfg(not(windows))]
    std::fs::rename(&temporary, &state_path)
        .map_err(|error| format!("cannot publish schedule server state: {error}"))?;

    Ok((
        token.clone(),
        ScheduleServeStateGuard {
            path: state_path,
            token,
        },
    ))
}

fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

fn write_schedule_export(
    project_root: &std::path::Path,
    relative_path: &str,
    contents: &[u8],
) -> Result<PathBuf, String> {
    let relative = std::path::Path::new(relative_path);
    if relative_path.chars().any(char::is_control)
        || relative.is_absolute()
        || relative
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return Err(
            "--output must be a project-relative path without `.` or `..` components".into(),
        );
    }
    let file_name = relative
        .file_name()
        .ok_or_else(|| "--output must name a file".to_owned())?;
    let parent = project_root.join(
        relative
            .parent()
            .unwrap_or_else(|| std::path::Path::new("")),
    );
    let canonical_parent = parent.canonicalize().map_err(|error| {
        format!(
            "cannot resolve output directory `{}`: {error}",
            parent.display()
        )
    })?;
    if !canonical_parent.starts_with(project_root) {
        return Err("--output directory resolves outside the project".into());
    }
    let destination = canonical_parent.join(file_name);
    match fs::symlink_metadata(&destination) {
        Ok(_) => {
            return Err(format!(
                "refusing to replace existing output `{}`",
                destination.display()
            ))
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => {
            return Err(format!(
                "cannot inspect output `{}`: {error}",
                destination.display()
            ))
        }
    }
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&destination)
        .map_err(|error| format!("cannot create output `{}`: {error}", destination.display()))?;
    if let Err(error) = file.write_all(contents).and_then(|()| file.sync_all()) {
        drop(file);
        let _ = fs::remove_file(&destination);
        return Err(format!(
            "cannot write output `{}`: {error}",
            destination.display()
        ));
    }
    Ok(destination)
}

fn task_usage() {
    eprintln!("Usage: zelyra task list <main.zyl> [--json] | task run <main.zyl> <command> [--args '<JSON-array>'] [--max-steps <n>]");
}

fn schedule_usage() {
    eprintln!("Usage: zelyra schedule list <main.zyl> [--json] | schedule export <main.zyl> [--format cron] [--output <project-relative-file>] | schedule trigger <main.zyl> --name <schedule>");
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::TimeZone;
    use std::time::{SystemTime, UNIX_EPOCH};

    #[test]
    fn scheduler_matches_five_field_cron_in_declared_timezones() {
        let berlin = chrono_tz::Europe::Berlin;
        let saturday_noon = chrono::Utc
            .with_ymd_and_hms(2026, 10, 17, 10, 0, 0)
            .single()
            .expect("valid UTC time")
            .with_timezone(&berlin);
        assert!(cron_matches_local_minute("0 12 * * 6", &saturday_noon).unwrap());
        assert!(!cron_matches_local_minute("1 12 * * 6", &saturday_noon).unwrap());
        assert!(cron_matches_local_minute("0 12 17 * 1", &saturday_noon).unwrap());

        let sunday_noon = chrono::Utc
            .with_ymd_and_hms(2026, 10, 18, 10, 0, 0)
            .single()
            .expect("valid UTC time")
            .with_timezone(&berlin);
        assert!(cron_matches_local_minute("0 12 * * 0", &sunday_noon).unwrap());
        assert!(cron_matches_local_minute("0 12 * * 7", &sunday_noon).unwrap());
        assert!(cron_matches_local_minute("*/15 12 18/2 * 1-5", &sunday_noon).unwrap());
    }

    #[test]
    fn scheduler_rejects_unknown_timezones_and_malformed_runtime_cron() {
        let schedule = zelyra_ast::ScheduleDef {
            name: "daily".into(),
            command: "daily".into(),
            cron: "0 12 * * 1".into(),
            timezone: Some("Mars/OlympusMons".into()),
            span: Default::default(),
        };
        assert!(parse_schedule_timezone(&schedule)
            .unwrap_err()
            .contains("unknown IANA timezone"));
        let utc = chrono::Utc
            .with_ymd_and_hms(2026, 10, 19, 12, 0, 0)
            .single()
            .expect("valid UTC time")
            .with_timezone(&chrono_tz::UTC);
        assert!(cron_matches_local_minute("60 12 * * 1", &utc).is_err());
    }

    #[test]
    fn scheduler_limits_parallel_jobs_and_prevents_overlap_per_schedule() {
        let mut active = std::collections::HashSet::new();
        assert!(claim_scheduler_job(&mut active, "one"));
        assert!(!claim_scheduler_job(&mut active, "one"));
        assert!(claim_scheduler_job(&mut active, "two"));
        assert!(claim_scheduler_job(&mut active, "three"));
        assert!(claim_scheduler_job(&mut active, "four"));
        assert!(!claim_scheduler_job(&mut active, "five"));
        active.remove("two");
        assert!(claim_scheduler_job(&mut active, "five"));
    }

    #[test]
    fn scheduler_reloads_the_current_source_and_drops_removed_or_changed_schedules() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock follows Unix epoch")
            .as_nanos();
        let project = std::env::temp_dir().join(format!(
            "zelyra-scheduler-source-{}-{nonce}",
            std::process::id()
        ));
        std::fs::create_dir_all(&project).expect("create scheduler project");
        let entry = project.join("main.zyl");
        let original = r#"command daily { handler: run_daily }
schedule daily { command: daily cron: "0 12 * * 6" timezone: "Europe/Berlin" }
fn run_daily() { }
fn main() { }
"#;
        std::fs::write(&entry, original).expect("write first schedule source");
        let due_at = chrono::Utc
            .with_ymd_and_hms(2026, 10, 17, 10, 0, 0)
            .single()
            .expect("valid UTC time");
        assert_eq!(
            due_schedule_handlers_from_source(entry.to_str().unwrap(), due_at).unwrap(),
            vec![("daily".into(), "run_daily".into())]
        );
        std::fs::write(
            &entry,
            "command daily { handler: run_daily } fn run_daily() { } fn main() { }",
        )
        .expect("remove the live schedule declaration");
        assert!(
            due_schedule_handlers_from_source(entry.to_str().unwrap(), due_at)
                .unwrap()
                .is_empty()
        );

        std::fs::write(
            &entry,
            r#"command daily { handler: run_changed }
schedule daily { command: daily cron: "0 12 * * 6" timezone: "Europe/Berlin" }
fn run_changed() { }
fn main() { }
"#,
        )
        .expect("change live handler declaration");
        assert_eq!(
            due_schedule_handlers_from_source(entry.to_str().unwrap(), due_at).unwrap(),
            vec![("daily".into(), "run_changed".into())]
        );
        std::fs::remove_dir_all(project).expect("remove scheduler project");
    }

    #[test]
    fn setup_uses_resident_schedules_and_removes_legacy_managed_export() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock follows Unix epoch")
            .as_nanos();
        let project = std::env::temp_dir().join(format!(
            "zelyra-schedule-setup-{}-{nonce}",
            std::process::id()
        ));
        std::fs::create_dir(&project).expect("create isolated project directory");
        let entry = project.join("main.zyl");
        std::fs::write(
            &entry,
            r#"
command weekly_email {
    handler: send_weekly_email
}
schedule weekly_email {
    command: weekly_email
    cron: "0 12 * * 6"
    timezone: "Europe/Berlin"
}
fn send_weekly_email() { }
fn main() { }
"#,
        )
        .expect("write valid scheduled project");

        let first = setup_declared_schedules(&entry).expect("prepare checked schedule");
        assert_eq!(first.len(), 1);
        assert!(first[0].contains("active Zelyra service"));
        let export = project.join(".zelyra/schedules.cron");
        assert!(!export.exists(), "setup must not create a host cron entry");

        let second = setup_declared_schedules(&entry).expect("repeat setup safely");
        assert_eq!(second.len(), 1);
        assert!(second[0].contains("active Zelyra service"));

        std::fs::create_dir(project.join(".zelyra")).expect("create legacy scheduler state");
        std::fs::write(
            &export,
            format!("{MANAGED_SCHEDULE_EXPORT_HEADER}\n0 12 * * 6 old-cron-entry\n"),
        )
        .expect("write old Zelyra-owned cron export");
        let third = setup_declared_schedules(&entry).expect("remove legacy cron export");
        assert!(third[0].contains("no longer uses project cron exports"));
        assert!(!export.exists(), "legacy managed cron export is removed");

        std::fs::write(
            &export,
            format!("{MANAGED_SCHEDULE_EXPORT_HEADER}\n0 12 * * 6 old-cron-entry\n"),
        )
        .expect("restore a legacy export before removing the declaration");
        std::fs::write(
            &entry,
            "command daily { handler: run_daily } fn run_daily() { } fn main() { }",
        )
        .expect("remove schedule declaration");
        let removed = setup_declared_schedules(&entry).expect("remove stale managed export");
        assert_eq!(removed.len(), 1);
        assert!(removed[0].contains("no schedules are declared"));
        assert!(!export.exists(), "stale managed schedule export is removed");

        std::fs::remove_dir_all(project).expect("remove isolated project");
    }

    #[cfg(unix)]
    #[test]
    fn setup_refuses_symlinked_schedule_state_directory() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock follows Unix epoch")
            .as_nanos();
        let parent = std::env::temp_dir().join(format!(
            "zelyra-schedule-symlink-{}-{nonce}",
            std::process::id()
        ));
        let project = parent.join("project");
        let outside = parent.join("outside");
        std::fs::create_dir_all(&project).expect("create isolated project directory");
        std::fs::create_dir(&outside).expect("create outside directory");
        std::fs::write(
            project.join("main.zyl"),
            "command daily { handler: run_daily } schedule daily { command: daily cron: \"0 0 * * *\" } fn run_daily() { } fn main() { }",
        )
        .expect("write valid scheduled project");
        std::os::unix::fs::symlink(&outside, project.join(".zelyra"))
            .expect("create state-directory symlink");

        let error = setup_declared_schedules(&project.join("main.zyl"))
            .expect_err("reject symlinked scheduler state");
        assert!(error.contains("unsafe state directory"));
        assert!(std::fs::read_dir(&outside)
            .expect("read outside directory")
            .next()
            .is_none());

        std::fs::remove_dir_all(parent).expect("remove isolated project tree");
    }

    #[test]
    fn setup_preserves_an_unmanaged_schedule_export() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock follows Unix epoch")
            .as_nanos();
        let project = std::env::temp_dir().join(format!(
            "zelyra-schedule-owned-{}-{nonce}",
            std::process::id()
        ));
        std::fs::create_dir_all(project.join(".zelyra")).expect("create project state");
        let entry = project.join("main.zyl");
        std::fs::write(
            &entry,
            "command daily { handler: run_daily } schedule daily { command: daily cron: \"0 0 * * *\" } fn run_daily() { } fn main() { }",
        )
        .expect("write valid scheduled project");
        let export = project.join(".zelyra/schedules.cron");
        std::fs::write(&export, "# user-managed\nkeep this file\n")
            .expect("write user-owned schedule file");

        let error =
            setup_declared_schedules(&entry).expect_err("do not remove a user-managed export");
        assert!(error.contains("not managed by Zelyra"));
        assert_eq!(
            std::fs::read_to_string(&export).unwrap(),
            "# user-managed\nkeep this file\n"
        );

        std::fs::remove_dir_all(project).expect("remove isolated project");
    }
}
